// Regenerate against an empty SQLite database when upgrading Better Auth.
import { Database } from "bun:sqlite";
import { getMigrations } from "better-auth/db/migration";
import { identityOptions } from "../src/identity";
import type { Env } from "../src/environment";
const options = identityOptions({
  API_ORIGIN: "https://api.example.com",
  WEBSITE_ORIGIN: "https://example.com",
} as Env);
const migration = await getMigrations({
  ...options,
  database: new Database(":memory:"),
});
await Bun.write(
  "migrations/0002_identity.sql",
  "-- Generated by Better Auth 1.7.14.\n" +
    (await migration.compileMigrations()) +
    "\n",
);
